-- =========================================================
-- Slot mappings
-- =========================================================

local SLOT_MAP = {
    INVTYPE_HEAD = 1,
    INVTYPE_NECK = 2,
    INVTYPE_SHOULDER = 3,
    INVTYPE_BODY = 4,
    INVTYPE_CHEST = 5,
    INVTYPE_ROBE = 5,
    INVTYPE_WAIST = 6,
    INVTYPE_LEGS = 7,
    INVTYPE_FEET = 8,
    INVTYPE_WRIST = 9,
    INVTYPE_HAND = 10,
    INVTYPE_FINGER = 11,
    INVTYPE_TRINKET = 13,
    INVTYPE_CLOAK = 15,
    INVTYPE_TABARD = 19,
    INVTYPE_WEAPON = 16,
    INVTYPE_2HWEAPON = 16,
    -- The ranged slot is gone: bows (RANGED) and guns, crossbows and wands
    -- (RANGEDRIGHT) all equip to the main hand now. Pointed at 18 they are
    -- compared against a slot nothing can occupy, which reads as no opinion and
    -- never sells them.
    INVTYPE_RANGED = 16,
    INVTYPE_RANGEDRIGHT = 16,
    INVTYPE_WEAPONMAINHAND = 16,
    INVTYPE_SHIELD = 17,
    INVTYPE_WEAPONOFFHAND = 17,
    INVTYPE_HOLDABLE = 17,
    -- Thrown weapons and relics were deleted rather than rehomed, so legacy
    -- items still carrying these equip nowhere. 18 -- permanently empty -- is
    -- the no-opinion answer that suits them.
    INVTYPE_THROWN = 18,
    INVTYPE_RELIC = 18,
}

-- Slots that may have two equipped items
local DUAL_SLOTS = {
    INVTYPE_FINGER = { 11, 12 },
    INVTYPE_TRINKET = { 13, 14 },
}

-- Merged lookup: invType → slot array (avoids per-call table allocation in
-- equipped-item comparison)
local SLOT_LOOKUP = {}
do
    for invType, slots in next, DUAL_SLOTS do
        SLOT_LOOKUP[invType] = slots
    end
    for invType, slotID in next, SLOT_MAP do
        if not SLOT_LOOKUP[invType] then
            SLOT_LOOKUP[invType] = { slotID }
        end
    end
end

enum.SLOT_LOOKUP = SLOT_LOOKUP
